import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Region, RemovalType } from '../types';
import { TYPE_COLORS, MOCK_VIDEO_URL } from '../constants';

interface VideoCanvasProps {
  regions: Region[];
  selectedRegionId: string | null;
  onRegionChange: (id: string, newRegion: Partial<Region>) => void;
  onRegionSelect: (id: string | null) => void;
  isPlaying: boolean;
  onVideoStateChange: (state: { duration: number; currentTime: number; isPlaying: boolean }) => void;
}

const VideoCanvas: React.FC<VideoCanvasProps> = ({
  regions,
  selectedRegionId,
  onRegionChange,
  onRegionSelect,
  isPlaying,
  onVideoStateChange
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [dragState, setDragState] = useState<{
    isDragging: boolean;
    isResizing: boolean;
    activeId: string | null;
    startX: number;
    startY: number;
    initialRect: Partial<Region>;
    handle?: string;
  } | null>(null);

  // Sync play/pause
  useEffect(() => {
    if (videoRef.current) {
      if (isPlaying) videoRef.current.play();
      else videoRef.current.pause();
    }
  }, [isPlaying]);

  // Video Events
  const handleTimeUpdate = () => {
    if (videoRef.current) {
      onVideoStateChange({
        duration: videoRef.current.duration,
        currentTime: videoRef.current.currentTime,
        isPlaying: !videoRef.current.paused
      });
    }
  };

  // --- Interaction Logic ---

  const getPercentageCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleStart = (
    e: React.MouseEvent | React.TouchEvent, 
    id: string, 
    action: 'move' | 'resize', 
    handle?: string
  ) => {
    e.stopPropagation();
    e.preventDefault(); // Prevent scrolling on mobile

    const region = regions.find(r => r.id === id);
    if (!region) return;

    onRegionSelect(id);
    const coords = getPercentageCoordinates(e);

    setDragState({
      isDragging: action === 'move',
      isResizing: action === 'resize',
      activeId: id,
      startX: coords.x,
      startY: coords.y,
      initialRect: { ...region },
      handle
    });
  };

  const handleMove = useCallback((e: MouseEvent | TouchEvent) => {
    if (!dragState || !dragState.activeId) return;

    const coords = getPercentageCoordinates(e as unknown as React.MouseEvent); // Cast for helper
    const deltaX = coords.x - dragState.startX;
    const deltaY = coords.y - dragState.startY;
    const initial = dragState.initialRect;

    let newRegion: Partial<Region> = {};

    if (dragState.isDragging) {
      newRegion = {
        x: Math.max(0, Math.min(100 - (initial.width || 0), (initial.x || 0) + deltaX)),
        y: Math.max(0, Math.min(100 - (initial.height || 0), (initial.y || 0) + deltaY))
      };
    } else if (dragState.isResizing && dragState.handle === 'se') {
      newRegion = {
        width: Math.max(5, (initial.width || 0) + deltaX),
        height: Math.max(5, (initial.height || 0) + deltaY)
      };
    }

    onRegionChange(dragState.activeId, newRegion);
  }, [dragState, onRegionChange]);

  const handleEnd = useCallback(() => {
    setDragState(null);
  }, []);

  // Global event listeners for drag outside container
  useEffect(() => {
    if (dragState) {
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', handleEnd);
      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
    }
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [dragState, handleMove, handleEnd]);


  return (
    <div 
      ref={containerRef} 
      className="relative w-full aspect-[9/16] bg-black overflow-hidden shadow-2xl rounded-lg select-none"
      onClick={() => onRegionSelect(null)} // Click bg to deselect
    >
      <video
        ref={videoRef}
        src={MOCK_VIDEO_URL}
        className="w-full h-full object-cover pointer-events-none"
        playsInline
        loop
        muted // Muted for auto-play possibility in demo
        onTimeUpdate={handleTimeUpdate}
      />

      {/* Region Overlays */}
      {regions.map((region) => {
        const isSelected = region.id === selectedRegionId;
        const styles = TYPE_COLORS[region.type];

        return (
          <div
            key={region.id}
            style={{
              left: `${region.x}%`,
              top: `${region.y}%`,
              width: `${region.width}%`,
              height: `${region.height}%`,
              borderColor: styles.primary,
              backgroundColor: isSelected ? styles.bg : 'transparent',
              borderStyle: region.type === RemovalType.SUBTITLE ? 'dashed' : 'solid',
            }}
            className={`absolute border-2 transition-colors duration-150 touch-none group ${isSelected ? 'z-20' : 'z-10'}`}
            onMouseDown={(e) => handleStart(e, region.id, 'move')}
            onTouchStart={(e) => handleStart(e, region.id, 'move')}
          >
            {/* Label (Only when selected) */}
            {isSelected && (
              <div 
                className="absolute -top-7 left-0 px-2 py-0.5 text-[10px] font-bold text-black uppercase tracking-wider rounded-sm shadow-sm"
                style={{ backgroundColor: styles.primary }}
              >
                {region.type === RemovalType.SUBTITLE ? 'Subtitle' : 'Watermark'}
              </div>
            )}

            {/* Resize Handle (Only when selected) */}
            {isSelected && (
              <div
                className="absolute -bottom-2 -right-2 w-6 h-6 bg-white rounded-full shadow-md flex items-center justify-center cursor-se-resize touch-none"
                onMouseDown={(e) => handleStart(e, region.id, 'resize', 'se')}
                onTouchStart={(e) => handleStart(e, region.id, 'resize', 'se')}
              >
                 <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="black" strokeWidth="3"><polyline points="21 15 21 21 15 21"/></svg>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default VideoCanvas;

import React from 'react';
import { Region, RemovalType, ModelType } from '../types';
import { TYPE_COLORS, MOCK_VIDEO_URL } from '../constants';
import { 
  PlayIcon, PauseIcon, PlusIcon, TrashIcon, 
  TypeIcon, EraserIcon, SparklesIcon, CheckIcon, ChevronDownIcon 
} from './Icons';

interface ControlPanelProps {
  selectedRegion: Region | null;
  isPlaying: boolean;
  onPlayToggle: () => void;
  onAddRegion: () => void;
  onDeleteRegion: (id: string) => void;
  onUpdateRegion: (id: string, updates: Partial<Region>) => void;
  onTranslate: () => void;
  videoTime: { current: number; total: number };
}

const ControlPanel: React.FC<ControlPanelProps> = ({
  selectedRegion,
  isPlaying,
  onPlayToggle,
  onAddRegion,
  onDeleteRegion,
  onUpdateRegion,
  onTranslate,
  videoTime
}) => {
  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const progress = (videoTime.current / (videoTime.total || 1)) * 100;

  // --- Render: Global Controls (When nothing selected) ---
  if (!selectedRegion) {
    return (
      <div className="flex flex-col gap-6 px-6 pb-8 pt-4 bg-zinc-900 rounded-t-3xl border-t border-zinc-800 shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
        {/* Drag handle */}
        <div className="w-full flex justify-center pb-2">
            <div className="w-12 h-1 bg-zinc-700 rounded-full"></div>
        </div>

        {/* Timeline (Read-only for demo) */}
        <div className="flex items-center gap-3 text-xs font-mono text-zinc-400">
          <span>{formatTime(videoTime.current)}</span>
          <div className="flex-1 h-1 bg-zinc-800 rounded-full overflow-hidden">
            <div className="h-full bg-emerald-500 transition-all duration-300" style={{ width: `${progress}%` }}></div>
          </div>
          <span>{formatTime(videoTime.total)}</span>
        </div>

        {/* Main Action Grid */}
        <div className="grid grid-cols-2 gap-4">
           {/* Play/Pause */}
           <button 
            onClick={onPlayToggle}
            className="flex flex-col items-center justify-center gap-2 p-4 bg-zinc-800 hover:bg-zinc-700 rounded-2xl transition-all"
          >
            {isPlaying ? <PauseIcon /> : <PlayIcon />}
            <span className="text-sm font-medium">{isPlaying ? 'Pause' : 'Preview'}</span>
          </button>

          {/* Add Removal Area */}
          <button 
            onClick={onAddRegion}
            className="flex flex-col items-center justify-center gap-2 p-4 bg-zinc-800 hover:bg-zinc-700 rounded-2xl transition-all border border-zinc-700/50"
          >
            <div className="p-2 bg-emerald-500/10 rounded-full text-emerald-400">
              <PlusIcon />
            </div>
            <span className="text-sm font-medium text-emerald-100">Add Eraser</span>
          </button>
        </div>

        {/* Start Button */}
        <button 
          onClick={onTranslate}
          className="w-full py-4 bg-emerald-500 hover:bg-emerald-400 text-black font-bold text-lg rounded-full shadow-lg shadow-emerald-900/50 transition-colors"
        >
          Export Video
        </button>
      </div>
    );
  }

  // --- Render: Contextual Controls (When region selected) ---
  const activeColor = TYPE_COLORS[selectedRegion.type].primary;

  return (
    <div className="flex flex-col gap-5 px-6 pb-8 pt-4 bg-zinc-900 rounded-t-3xl border-t border-zinc-800 animate-in slide-in-from-bottom duration-300">
       {/* Drag handle */}
       <div className="w-full flex justify-center pb-2" onClick={() => onUpdateRegion(selectedRegion.id, {}) /* dummy to keep focus */}>
            <div className="w-12 h-1 bg-zinc-600 rounded-full"></div>
        </div>

      {/* Header with Close/Delete */}
      <div className="flex justify-between items-center mb-2">
        <h3 className="text-lg font-semibold text-white">Eraser Settings</h3>
        <button 
          onClick={() => onDeleteRegion(selectedRegion.id)}
          className="p-2 text-red-400 bg-red-400/10 hover:bg-red-400/20 rounded-full transition-colors"
        >
          <TrashIcon />
        </button>
      </div>

      {/* 1. What are we erasing? (Type Toggle) */}
      <div className="flex bg-black p-1 rounded-xl border border-zinc-800">
        <button
          onClick={() => onUpdateRegion(selectedRegion.id, { type: RemovalType.SUBTITLE })}
          className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-lg text-sm font-medium transition-all ${
            selectedRegion.type === RemovalType.SUBTITLE 
              ? 'bg-zinc-800 text-white shadow-md' 
              : 'text-zinc-500 hover:text-zinc-300'
          }`}
        >
          <TypeIcon />
          <span>Text / Subtitle</span>
          {selectedRegion.type === RemovalType.SUBTITLE && <CheckIcon />}
        </button>
        <button
          onClick={() => onUpdateRegion(selectedRegion.id, { type: RemovalType.WATERMARK })}
          className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-lg text-sm font-medium transition-all ${
            selectedRegion.type === RemovalType.WATERMARK 
              ? 'bg-zinc-800 text-white shadow-md' 
              : 'text-zinc-500 hover:text-zinc-300'
          }`}
        >
          <EraserIcon />
          <span>Object / Logo</span>
          {selectedRegion.type === RemovalType.WATERMARK && <CheckIcon />}
        </button>
      </div>

      {/* 2. How powerful? (Model Selection) */}
      <div className="space-y-3">
        <label className="text-xs font-semibold text-zinc-500 uppercase tracking-wide ml-1">Removal Quality</label>

        <div className="grid grid-cols-2 gap-3">
            {/* Basic Model */}
            <button
                onClick={() => onUpdateRegion(selectedRegion.id, { model: ModelType.BASIC })}
                className={`relative p-4 rounded-xl border text-left transition-all ${
                    selectedRegion.model === ModelType.BASIC
                    ? 'border-emerald-500/50 bg-emerald-500/10'
                    : 'border-zinc-800 bg-zinc-800/50 hover:bg-zinc-800'
                }`}
            >
                <div className="text-sm font-bold text-white mb-1">Standard</div>
                <div className="text-xs text-zinc-400">Faster processing. Best for simple backgrounds.</div>
                {selectedRegion.model === ModelType.BASIC && (
                    <div className="absolute top-3 right-3 text-emerald-500"><CheckIcon /></div>
                )}
            </button>

             {/* Advanced Model */}
             <button
                onClick={() => onUpdateRegion(selectedRegion.id, { model: ModelType.ADVANCED })}
                className={`relative p-4 rounded-xl border text-left transition-all ${
                    selectedRegion.model === ModelType.ADVANCED
                    ? 'border-purple-500/50 bg-purple-500/10'
                    : 'border-zinc-800 bg-zinc-800/50 hover:bg-zinc-800'
                }`}
            >
                <div className="flex items-center gap-1 text-sm font-bold text-white mb-1">
                    <SparklesIcon /> AI Pro
                </div>
                <div className="text-xs text-zinc-400">Deep pixel regeneration. For complex scenes.</div>
                {selectedRegion.model === ModelType.ADVANCED && (
                    <div className="absolute top-3 right-3 text-purple-500"><CheckIcon /></div>
                )}
            </button>
        </div>
      </div>
    </div>
  );
};

export default ControlPanel;

import React, { useState, useCallback } from 'react';
import VideoCanvas from './components/VideoCanvas';
import ControlPanel from './components/ControlPanel';
import { Region, RemovalType, ModelType } from './types';
import { generateId } from './constants';
import { ChevronDownIcon } from './components/Icons';

const App = () => {
  const [regions, setRegions] = useState<Region[]>([]);
  const [selectedRegionId, setSelectedRegionId] = useState<string | null>(null);

  const [videoState, setVideoState] = useState({
    isPlaying: false,
    currentTime: 0,
    duration: 0
  });

  // --- Actions ---

  const addRegion = useCallback(() => {
    const newRegion: Region = {
      id: generateId(),
      x: 25,
      y: 40,
      width: 50,
      height: 20,
      type: RemovalType.SUBTITLE, // Default to most common
      model: ModelType.BASIC
    };
    setRegions(prev => [...prev, newRegion]);
    setSelectedRegionId(newRegion.id);
    // Pause video when editing
    setVideoState(prev => ({ ...prev, isPlaying: false }));
  }, []);

  const updateRegion = useCallback((id: string, updates: Partial<Region>) => {
    setRegions(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  }, []);

  const deleteRegion = useCallback((id: string) => {
    setRegions(prev => prev.filter(r => r.id !== id));
    if (selectedRegionId === id) setSelectedRegionId(null);
  }, [selectedRegionId]);

  const handleRegionSelect = useCallback((id: string | null) => {
    setSelectedRegionId(id);
  }, []);

  const handleExport = () => {
    alert(`Exporting video with ${regions.length} removal zones. \nConfiguration sent to backend.`);
    console.log("Payload:", JSON.stringify(regions, null, 2));
  };

  const selectedRegion = regions.find(r => r.id === selectedRegionId) || null;

  return (
    <div className="fixed inset-0 bg-black flex flex-col font-sans text-white">
      {/* Header */}
      <header className="flex items-center justify-between px-4 py-4 z-10">
        <button className="p-2 rounded-full bg-zinc-800/50 backdrop-blur-md">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2"><path d="M15 18l-6-6 6-6"/></svg>
        </button>
        <h1 className="text-sm font-semibold tracking-wide">VIDEO TRANSLATOR</h1>
        <button className="p-2 text-zinc-400">
             <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg>
        </button>
      </header>

      {/* Main Canvas Area */}
      <main className="flex-1 flex flex-col justify-center px-4 relative">
        {/* Instruction Overlay (Fades out when regions exist) */}
        {regions.length === 0 && (
          <div className="absolute top-10 left-0 right-0 z-10 flex flex-col items-center pointer-events-none opacity-70">
            <p className="text-zinc-400 text-sm mb-1">Clean up your video</p>
            <h2 className="text-2xl font-bold text-white">Tap 'Add Eraser' to start</h2>
          </div>
        )}

        <VideoCanvas 
          regions={regions}
          selectedRegionId={selectedRegionId}
          onRegionChange={updateRegion}
          onRegionSelect={handleRegionSelect}
          isPlaying={videoState.isPlaying}
          onVideoStateChange={setVideoState}
        />

        {/* Helper text under canvas */}
        {selectedRegion && (
            <div className="mt-4 text-center text-zinc-500 text-xs animate-pulse">
                Drag center to move • Drag corner to resize
            </div>
        )}
      </main>

      {/* Bottom Sheet / Controls */}
      <div className="z-20 w-full max-w-md mx-auto">
        <ControlPanel 
          selectedRegion={selectedRegion}
          isPlaying={videoState.isPlaying}
