import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Region, RemovalType } from '../types';
import { TYPE_COLORS, MOCK_VIDEO_URL } from '../constants';

interface VideoCanvasProps {
  regions: Region[];
  selectedRegionId: string | null;
  onRegionChange: (id: string, newRegion: Partial<Region>) => void;
  onRegionSelect: (id: string | null) => void;
  isPlaying: boolean;
  onVideoStateChange: (state: { duration: number; currentTime: number; isPlaying: boolean }) => void;
}

const VideoCanvas: React.FC<VideoCanvasProps> = ({
  regions,
  selectedRegionId,
  onRegionChange,
  onRegionSelect,
  isPlaying,
  onVideoStateChange
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [dragState, setDragState] = useState<{
    isDragging: boolean;
    isResizing: boolean;
    activeId: string | null;
    startX: number;
    startY: number;
    initialRect: Partial<Region>;
    handle?: string;
  } | null>(null);

  // Sync play/pause
  useEffect(() => {
    if (videoRef.current) {
      if (isPlaying) videoRef.current.play().catch(e => console.log("Autoplay blocked:", e));
      else videoRef.current.pause();
    }
  }, [isPlaying]);

  // Video Events
  const handleTimeUpdate = () => {
    if (videoRef.current) {
      onVideoStateChange({
        duration: videoRef.current.duration || 0,
        currentTime: videoRef.current.currentTime || 0,
        isPlaying: !videoRef.current.paused
      });
    }
  };

  // --- Interaction Logic ---

  const getPercentageCoordinates = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();

    // Robust coordinate extraction for both React and Native events
    let clientX = 0;
    let clientY = 0;

    if ('touches' in e && e.touches.length > 0) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else if ('clientX' in e) {
      clientX = (e as MouseEvent).clientX;
      clientY = (e as MouseEvent).clientY;
    }

    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleStart = (
    e: React.MouseEvent | React.TouchEvent, 
    id: string, 
    action: 'move' | 'resize', 
    handle?: string
  ) => {
    e.stopPropagation();
    // preventDefault helps stop scrolling/selecting, but we must be careful not to block click events entirely if needed
    // For dragging, it's usually good.
    if (e.cancelable) e.preventDefault();

    const region = regions.find(r => r.id === id);
    if (!region) return;

    onRegionSelect(id);
    const coords = getPercentageCoordinates(e);

    setDragState({
      isDragging: action === 'move',
      isResizing: action === 'resize',
      activeId: id,
      startX: coords.x,
      startY: coords.y,
      initialRect: { ...region },
      handle
    });
  };

  const handleMove = useCallback((e: MouseEvent | TouchEvent) => {
    if (!dragState || !dragState.activeId) return;

    if (e.cancelable) e.preventDefault(); // Stop scrolling while dragging

    const coords = getPercentageCoordinates(e);
    const deltaX = coords.x - dragState.startX;
    const deltaY = coords.y - dragState.startY;
    const initial = dragState.initialRect;

    let newRegion: Partial<Region> = {};

    if (dragState.isDragging) {
      newRegion = {
        x: Math.max(0, Math.min(100 - (initial.width || 0), (initial.x || 0) + deltaX)),
        y: Math.max(0, Math.min(100 - (initial.height || 0), (initial.y || 0) + deltaY))
      };
    } else if (dragState.isResizing && dragState.handle === 'se') {
      newRegion = {
        width: Math.max(10, (initial.width || 0) + deltaX), // Min width 10%
        height: Math.max(5, (initial.height || 0) + deltaY)  // Min height 5%
      };
    }

    onRegionChange(dragState.activeId, newRegion);
  }, [dragState, onRegionChange]);

  const handleEnd = useCallback(() => {
    setDragState(null);
  }, []);

  // Global event listeners for drag outside container
  useEffect(() => {
    if (dragState) {
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', handleEnd);
      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
    }
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [dragState, handleMove, handleEnd]);


  return (
    <div 
      ref={containerRef} 
      className="relative w-full aspect-[9/16] bg-zinc-900 overflow-hidden shadow-2xl rounded-lg select-none touch-none"
      onClick={() => onRegionSelect(null)}
      // Add a subtle grid pattern so it's not just a black hole if video fails
      style={{
        backgroundImage: 'radial-gradient(circle, #333 1px, transparent 1px)',
        backgroundSize: '20px 20px'
      }}
    >
      <video
        ref={videoRef}
        src={MOCK_VIDEO_URL}
        className="w-full h-full object-cover pointer-events-none"
        playsInline
        loop
        muted
        onTimeUpdate={handleTimeUpdate}
      />

      {/* Region Overlays */}
      {regions.map((region) => {
        const isSelected = region.id === selectedRegionId;
        const styles = TYPE_COLORS[region.type];

        return (
          <div
            key={region.id}
            style={{
              left: `${region.x}%`,
              top: `${region.y}%`,
              width: `${region.width}%`,
              height: `${region.height}%`,
              borderColor: styles.primary,
              backgroundColor: isSelected ? styles.bg : 'transparent',
              borderStyle: region.type === RemovalType.SUBTITLE ? 'dashed' : 'solid',
            }}
            className={`absolute border-2 transition-colors duration-150 group ${isSelected ? 'z-20' : 'z-10'}`}
            onMouseDown={(e) => handleStart(e, region.id, 'move')}
            onTouchStart={(e) => handleStart(e, region.id, 'move')}
          >
            {/* Label (Only when selected) */}
            {isSelected && (
              <div 
                className="absolute -top-8 left-0 px-2 py-1 text-[10px] font-bold text-black uppercase tracking-wider rounded-sm shadow-sm"
                style={{ backgroundColor: styles.primary }}
              >
                {region.type === RemovalType.SUBTITLE ? 'Subtitle' : 'Watermark'}
              </div>
            )}

            {/* Resize Handle (Bigger hit area for mobile) */}
            {isSelected && (
              <div
                className="absolute -bottom-4 -right-4 w-10 h-10 flex items-center justify-center cursor-se-resize z-30"
                onMouseDown={(e) => handleStart(e, region.id, 'resize', 'se')}
                onTouchStart={(e) => handleStart(e, region.id, 'resize', 'se')}
              >
                 {/* Visual handle is smaller, but touch target is 40x40px */}
                 <div className="w-5 h-5 bg-white rounded-full shadow-lg border border-zinc-300 flex items-center justify-center">
                    <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="black" strokeWidth="3"><polyline points="21 15 21 21 15 21"/></svg>
                 </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default VideoCanvas;

