  return (
    <div 
      ref={containerRef} 
      className="relative w-full aspect-[9/16] bg-zinc-800 overflow-hidden shadow-2xl rounded-lg select-none touch-none"
      onClick={() => onRegionSelect(null)}
      style={{
        backgroundImage: 'radial-gradient(circle, #52525b 1px, transparent 1px)', // Lighter grid
        backgroundSize: '20px 20px'
      }}
    >
      <video
        ref={videoRef}
        src={MOCK_VIDEO_URL}
        poster={MOCK_POSTER_URL}
        className="w-full h-full object-cover pointer-events-none"
        playsInline
        loop
        muted
        onTimeUpdate={handleTimeUpdate}
        onLoadedMetadata={handleLoadedMetadata}
        onError={(e) => console.error("Video error:", e)}
      />

      {/* Empty State Call-to-Action */}
      {regions.length === 0 && (
        <div className="absolute inset-0 flex items-center justify-center z-10 pointer-events-none">
          <button 
            onClick={(e) => { e.stopPropagation(); onAddFirstRegion(); }}
            className="pointer-events-auto flex flex-col items-center gap-3 animate-bounce"
          >
            <div className="w-16 h-16 rounded-full bg-emerald-500/20 flex items-center justify-center border-2 border-emerald-500 shadow-[0_0_30px_rgba(16,185,129,0.3)] backdrop-blur-sm">
                <PlusIcon />
            </div>
            <span className="font-bold text-white text-lg drop-shadow-md bg-black/50 px-3 py-1 rounded-full">
              Tap to Add Area
            </span>
          </button>
        </div>
      )}

      {/* Region Overlays */}
      {regions.map((region) => {
        const isSelected = region.id === selectedRegionId;
        const styles = TYPE_COLORS[region.type];

        return (
          <div
            key={region.id}
            style={{
              left: `${region.x}%`,
              top: `${region.y}%`,
              width: `${region.width}%`,
              height: `${region.height}%`,
              borderColor: styles.primary,
              backgroundColor: isSelected ? styles.bg : 'transparent',
              borderStyle: region.type === RemovalType.SUBTITLE ? 'dashed' : 'solid',
            }}
            className={`absolute border-2 transition-colors duration-150 group ${isSelected ? 'z-20' : 'z-10'}`}
            onMouseDown={(e) => handleStart(e, region.id, 'move')}
            onTouchStart={(e) => handleStart(e, region.id, 'move')}
          >
            {/* Label */}
            {isSelected && (
              <div 
                className="absolute -top-8 left-0 px-2 py-1 text-[10px] font-bold text-black uppercase tracking-wider rounded-sm shadow-sm"
                style={{ backgroundColor: styles.primary }}
              >
                {region.type === RemovalType.SUBTITLE ? 'Subtitle' : 'Watermark'}
              </div>
            )}

            {/* Resize Handle */}
            {isSelected && (
              <div
                className="absolute -bottom-4 -right-4 w-10 h-10 flex items-center justify-center cursor-se-resize z-30"
                onMouseDown={(e) => handleStart(e, region.id, 'resize', 'se')}
                onTouchStart={(e) => handleStart(e, region.id, 'resize', 'se')}
              >
                 <div className="w-5 h-5 bg-white rounded-full shadow-lg border border-zinc-300 flex items-center justify-center">
                    <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="black" strokeWidth="3"><polyline points="21 15 21 21 15 21"/></svg>
                 </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

