import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Region, RemovalType } from '../types';
import { MOCK_VIDEO_URL, MOCK_POSTER_URL, TYPE_COLORS } from '../constants';
import { PlayIcon, PauseIcon, PlusIcon, CopyIcon, TrashIcon, ResizeIcon } from './Icons';

interface VideoCanvasProps {
  regions: Region[];
  selectedRegionId: string | null;
  onRegionChange: (id: string, newRegion: Partial<Region>) => void;
  onRegionSelect: (id: string | null) => void;
  isPlaying: boolean;
  onPlayToggle: () => void;
  videoState: { duration: number; currentTime: number };
  onTimeUpdate: (current: number, duration: number) => void;
  onAddFirstRegion: () => void;
  onDuplicate: () => void;
  onDelete: () => void;
}

const VideoCanvas: React.FC<VideoCanvasProps> = ({
  regions,
  selectedRegionId,
  onRegionChange,
  onRegionSelect,
  isPlaying,
  onPlayToggle,
  videoState,
  onTimeUpdate,
  onAddFirstRegion,
  onDuplicate,
  onDelete
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [dragState, setDragState] = useState<{
    isDragging: boolean;
    isResizing: boolean;
    activeId: string | null;
    startX: number;
    startY: number;
    initialRect: Partial<Region>;
    handle?: string;
  } | null>(null);

  useEffect(() => {
    if (videoRef.current) {
      if (isPlaying) videoRef.current.play().catch(console.error);
      else videoRef.current.pause();
    }
  }, [isPlaying]);

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      onTimeUpdate(videoRef.current.currentTime, videoRef.current.duration);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const getPercentageCoordinates = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    let clientX = 0, clientY = 0;

    if ('touches' in e && e.touches.length > 0) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else if ('clientX' in e) {
      clientX = (e as MouseEvent).clientX;
      clientY = (e as MouseEvent).clientY;
    }

    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleStart = (e: React.MouseEvent | React.TouchEvent, id: string, action: 'move' | 'resize') => {
    e.stopPropagation();
    if (e.cancelable) e.preventDefault();
    const region = regions.find(r => r.id === id);
    if (!region) return;

    onRegionSelect(id);
    const coords = getPercentageCoordinates(e);

    setDragState({
      isDragging: action === 'move',
      isResizing: action === 'resize',
      activeId: id,
      startX: coords.x,
      startY: coords.y,
      initialRect: { ...region }
    });
  };

  const handleMove = useCallback((e: MouseEvent | TouchEvent) => {
    if (!dragState || !dragState.activeId) return;
    if (e.cancelable) e.preventDefault();

    const coords = getPercentageCoordinates(e);
    const deltaX = coords.x - dragState.startX;
    const deltaY = coords.y - dragState.startY;
    const initial = dragState.initialRect;

    let newRegion: Partial<Region> = {};
    if (dragState.isDragging) {
      newRegion = {
        x: Math.max(0, Math.min(100 - (initial.width || 0), (initial.x || 0) + deltaX)),
        y: Math.max(0, Math.min(100 - (initial.height || 0), (initial.y || 0) + deltaY))
      };
    } else if (dragState.isResizing) {
      newRegion = {
        width: Math.max(10, (initial.width || 0) + deltaX),
        height: Math.max(5, (initial.height || 0) + deltaY)
      };
    }
    onRegionChange(dragState.activeId, newRegion);
  }, [dragState, onRegionChange]);

  const handleEnd = useCallback(() => setDragState(null), []);

  const handleTypeToggle = (e: React.MouseEvent, region: Region) => {
    e.stopPropagation();
    const newType = region.type === RemovalType.SUBTITLE ? RemovalType.WATERMARK : RemovalType.SUBTITLE;
    onRegionChange(region.id, { type: newType });
  };

  const handleDuplicate = (e: React.MouseEvent) => {
      e.stopPropagation();
      onDuplicate();
  }

  const handleDelete = (e: React.MouseEvent) => {
      e.stopPropagation();
      onDelete();
  }

  useEffect(() => {
    if (dragState) {
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', handleEnd);
      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
    }
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [dragState, handleMove, handleEnd]);

  const progressPercent = (videoState.currentTime / (videoState.duration || 1)) * 100;

  return (
    <div className="w-full space-y-2">
        <div 
            ref={containerRef} 
            className="relative w-full aspect-video bg-zinc-900 rounded-lg overflow-hidden shadow-lg touch-none group select-none"
            onClick={() => onRegionSelect(null)}
        >
            <video
                ref={videoRef}
                src={MOCK_VIDEO_URL}
                poster={MOCK_POSTER_URL}
                className="w-full h-full object-cover pointer-events-none"
                playsInline
                loop
                muted
                onTimeUpdate={handleTimeUpdate}
            />

            {regions.length === 0 && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-30">
                     <button 
                        onClick={(e) => { e.stopPropagation(); onAddFirstRegion(); }}
                        className="pointer-events-auto animate-bounce p-3 bg-emerald-500/20 rounded-full border border-emerald-500 text-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.4)]"
                    >
                        <PlusIcon />
                    </button>
                    <div className="absolute top-2/3 text-center px-6 opacity-80">
                         <p className="text-white text-xs font-medium">点击 + 号添加擦除区域</p>
                    </div>
                </div>
            )}

            {regions.map((region) => {
                const isSelected = region.id === selectedRegionId;
                const typeStyle = TYPE_COLORS[region.type];

                return (
                    <div
                        key={region.id}
                        style={{
                            left: `${region.x}%`,
                            top: `${region.y}%`,
                            width: `${region.width}%`,
                            height: `${region.height}%`,
                            borderColor: typeStyle.primary,
                            backgroundColor: isSelected ? typeStyle.bg : 'transparent',
                            borderStyle: region.type === RemovalType.SUBTITLE ? 'dashed' : 'solid',
                        }}
                        className={`absolute border-2 touch-none transition-colors duration-150
                            ${isSelected ? 'z-20' : 'z-10'}
                        `}
                        onMouseDown={(e) => handleStart(e, region.id, 'move')}
                        onTouchStart={(e) => handleStart(e, region.id, 'move')}
                    >
                        {/* Box Label (Simplified to icon/text when not selected, or hidden) */}
                        {!isSelected && (
                            <div 
                                className="absolute -top-5 left-0 px-1 py-0.5 rounded-sm text-[8px] font-bold text-black uppercase tracking-wider opacity-80"
                                style={{ backgroundColor: typeStyle.primary }}
                            >
                                {region.type === RemovalType.SUBTITLE ? 'SUB' : 'LOGO'}
                            </div>
                        )}

                        {/* --- CONTEXTUAL ACTION BAR (Above Box) --- */}
                        {isSelected && (
                            <div 
                                className="absolute -top-10 left-1/2 -translate-x-1/2 flex items-center gap-1 p-1 bg-black/90 backdrop-blur-md rounded-lg shadow-xl border border-zinc-700 z-50 animate-in fade-in slide-in-from-bottom-2 duration-200"
                                onMouseDown={(e) => e.stopPropagation()} 
                                onTouchStart={(e) => e.stopPropagation()}
                            >
                                {/* Switch Type */}
                                <button 
                                    onClick={(e) => handleTypeToggle(e, region)}
                                    className="p-1.5 rounded-md hover:bg-zinc-700 text-white flex items-center gap-1.5"
                                >
                                    <div className={`w-2 h-2 rounded-full ${region.type === RemovalType.SUBTITLE ? 'bg-emerald-500' : 'bg-violet-500'}`} />
                                    <span className="text-[10px] font-bold leading-none">{region.type === RemovalType.SUBTITLE ? '字幕' : '水印'}</span>
                                </button>

                                <div className="w-px h-3 bg-zinc-700 mx-0.5"></div>

                                {/* Duplicate */}
                                <button 
                                    onClick={handleDuplicate}
                                    className="p-1.5 rounded-md hover:bg-zinc-700 text-zinc-300 hover:text-white"
                                >
                                    <CopyIcon />
                                </button>

                                <div className="w-px h-3 bg-zinc-700 mx-0.5"></div>

                                {/* Delete */}
                                <button 
                                    onClick={handleDelete}
                                    className="p-1.5 rounded-md hover:bg-red-500/20 text-red-400"
                                >
                                    <TrashIcon />
                                </button>
                            </div>
                        )}

                        {/* --- ENHANCED RESIZE HANDLE --- */}
                        {isSelected && (
                            <>
                                {/* Visual corners */}
                                <div className="absolute -top-1 -left-1 w-2 h-2 bg-white rounded-full border border-black" />
                                <div className="absolute -top-1 -right-1 w-2 h-2 bg-white rounded-full border border-black" />
                                <div className="absolute -bottom-1 -left-1 w-2 h-2 bg-white rounded-full border border-black" />

                                {/* Main Resize Button */}
                                <div 
                                    className="absolute -bottom-3 -right-3 w-8 h-8 flex items-center justify-center bg-transparent z-40 touch-manipulation"
                                    onMouseDown={(e) => handleStart(e, region.id, 'resize')}
                                    onTouchStart={(e) => handleStart(e, region.id, 'resize')}
                                >
                                     <div 
                                        className="w-5 h-5 rounded-full shadow-lg flex items-center justify-center text-white text-[10px]"
                                        style={{ backgroundColor: typeStyle.primary }}
                                     >
                                        <ResizeIcon />
                                     </div>
                                </div>
                            </>
                        )}
                    </div>
                );
            })}
        </div>

        {/* Minimal Player Controls */}
        <div className="flex items-center gap-3 px-1 py-1">
            <button onClick={onPlayToggle} className="text-white hover:text-emerald-400 transition-colors">
                {isPlaying ? <PauseIcon /> : <PlayIcon />}
            </button>

            <div className="flex-1 relative h-6 flex items-center group cursor-pointer">
                <div className="absolute left-0 right-0 h-0.5 bg-zinc-700 rounded-full"></div>
                <div className="absolute left-0 h-0.5 bg-emerald-500 rounded-full" style={{ width: `${progressPercent}%` }}></div>
                <div className="absolute h-3 w-3 bg-white rounded-full shadow-md transform -translate-x-1/2" style={{ left: `${progressPercent}%` }}></div>
            </div>

            <div className="text-[10px] font-mono text-zinc-400">
                <span className="text-white">{formatTime(videoState.currentTime)}</span>
                <span className="opacity-50">/{formatTime(videoState.duration)}</span>
            </div>
        </div>
    </div>
  );
};

