    duration: 0
  });

  // Global Config State (Translation only)
  const [config, setConfig] = useState<TranslationConfig>({
    sourceLang: 'zh-CN',
    targetLang: 'en-US',
    dynamicDuration: true,
    removeSubtitle: true,
    multiSpeaker: false,
    voice: '温柔女声'
  });

  // --- Handlers ---

  const addRegion = useCallback(() => {
    // Offset slightly from previous or center
    const lastRegion = regions[regions.length - 1];
    const newRegion: Region = {
      id: generateId(),
      x: lastRegion ? Math.max(5, lastRegion.x + 5) : 25,
      y: lastRegion ? Math.max(5, lastRegion.y + 5) : 70,
      width: lastRegion ? lastRegion.width : 50,
      height: lastRegion ? lastRegion.height : 12,
      type: RemovalType.SUBTITLE, // Default to subtitle
      model: ModelType.BASIC
    };
    setRegions(prev => [...prev, newRegion]);
    setSelectedRegionId(newRegion.id);
    setVideoState(prev => ({ ...prev, isPlaying: false }));
  }, [regions]);

  const duplicateRegion = useCallback(() => {
    if (!selectedRegionId) return;
    const original = regions.find(r => r.id === selectedRegionId);
    if (!original) return;

    const newRegion: Region = {
        ...original,
        id: generateId(),
        x: Math.min(original.x + 5, 80),
        y: Math.min(original.y + 5, 80)
    };
    setRegions(prev => [...prev, newRegion]);
    setSelectedRegionId(newRegion.id);
  }, [regions, selectedRegionId]);

  const deleteRegion = useCallback(() => {
    if (!selectedRegionId) return;
    setRegions(prev => prev.filter(r => r.id !== selectedRegionId));
    setSelectedRegionId(null);
  }, [selectedRegionId]);

  const updateRegion = useCallback((id: string, updates: Partial<Region>) => {
    setRegions(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  }, []);

  const updateSelectedRegion = useCallback((updates: Partial<Region>) => {
    if (selectedRegionId) {
        updateRegion(selectedRegionId, updates);
    }
  }, [selectedRegionId, updateRegion]);

  const handleStartTranslation = () => {
    alert('Started Task:\n' + JSON.stringify({ config, regions }, null, 2));
