import React, { useState, useCallback } from 'react';
import VideoCanvas from './components/VideoCanvas';
import ControlPanel from './components/ControlPanel';
import { Region, RemovalType, ModelType, TranslationConfig } from './types';
import { generateId } from './constants';

const App = () => {
  // Video Regions State
  const [regions, setRegions] = useState<Region[]>([]);
  const [selectedRegionId, setSelectedRegionId] = useState<string | null>(null);

  // Video Player State
  const [videoState, setVideoState] = useState({
    isPlaying: false,
    currentTime: 0,
    duration: 0
  });

  // Global Config State (Translation only)
  const [config, setConfig] = useState<TranslationConfig>({
    sourceLang: 'zh-CN',
    targetLang: 'en-US',
    dynamicDuration: true,
    removeSubtitle: true,
    multiSpeaker: false,
    voice: '温柔女声'
  });

  // --- Handlers ---

  const addRegion = useCallback((type: RemovalType) => {
    // Offset slightly from previous or center
    const lastRegion = regions[regions.length - 1];
    const newRegion: Region = {
      id: generateId(),
      x: lastRegion ? Math.max(5, lastRegion.x + 5) : 30,
      y: lastRegion ? Math.max(5, lastRegion.y + 5) : 40,
      width: 40,
      height: 15,
      type: type,
      model: ModelType.BASIC
    };
    setRegions(prev => [...prev, newRegion]);
    setSelectedRegionId(newRegion.id);
    setVideoState(prev => ({ ...prev, isPlaying: false }));
  }, [regions]);

  const duplicateRegion = useCallback(() => {
    if (!selectedRegionId) return;
    const original = regions.find(r => r.id === selectedRegionId);
    if (!original) return;

    const newRegion: Region = {
        ...original,
        id: generateId(),
        x: Math.min(original.x + 5, 80),
        y: Math.min(original.y + 5, 80)
    };
    setRegions(prev => [...prev, newRegion]);
    setSelectedRegionId(newRegion.id);
  }, [regions, selectedRegionId]);

  const deleteRegion = useCallback(() => {
    if (!selectedRegionId) return;
    setRegions(prev => prev.filter(r => r.id !== selectedRegionId));
    setSelectedRegionId(null);
  }, [selectedRegionId]);

  const updateRegion = useCallback((id: string, updates: Partial<Region>) => {
    setRegions(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  }, []);

  const updateSelectedRegion = useCallback((updates: Partial<Region>) => {
    if (selectedRegionId) {
        updateRegion(selectedRegionId, updates);
    }
  }, [selectedRegionId, updateRegion]);

  const handleStartTranslation = () => {
    alert('Started Task:\n' + JSON.stringify({ config, regions }, null, 2));
  };

  const handleTimeUpdate = (currentTime: number, duration: number) => {
    setVideoState(prev => ({ ...prev, currentTime, duration }));
  };

  const selectedRegion = regions.find(r => r.id === selectedRegionId) || null;

  return (
    <div className="fixed inset-0 h-[100dvh] bg-black flex flex-col font-sans text-white overflow-hidden">
      {/* App Header */}
      <header className="flex-none flex items-center justify-between px-4 py-3 z-20 bg-[#18181b] border-b border-zinc-800">
        <button className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-zinc-800 transition-colors">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2"><path d="M15 18l-6-6 6-6"/></svg>
        </button>
        <h1 className="text-base font-semibold tracking-wide text-white">视频翻译</h1>
        <button className="w-8 h-8 flex items-center justify-center text-white hover:bg-zinc-800 rounded-full">
             <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="5" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="12" cy="19" r="1.5"/></svg>
        </button>
      </header>

      {/* Main Content Area: Flex Column */}
      <div className="flex-1 flex flex-col overflow-hidden relative">

        {/* Top: Video Canvas (Fixed height approx 40% of screen or auto) */}
        <div className="flex-none bg-[#09090b] pt-4 pb-2 px-4 z-10">
            <VideoCanvas 
                regions={regions}
                selectedRegionId={selectedRegionId}
                onRegionChange={updateRegion}
                onRegionSelect={setSelectedRegionId}
                isPlaying={videoState.isPlaying}
                onPlayToggle={() => setVideoState(s => ({ ...s, isPlaying: !s.isPlaying }))}
                videoState={videoState}
                onTimeUpdate={handleTimeUpdate}
                onAddFirstRegion={() => addRegion(RemovalType.SUBTITLE)}
                onDuplicate={duplicateRegion}
                onDelete={deleteRegion}
                showRegions={config.removeSubtitle}
            />
        </div>

        {/* Middle/Bottom: Scrollable Settings Panel */}
        <div className="flex-1 overflow-hidden bg-[#121212] relative z-20">
            <ControlPanel 
                config={config}
                selectedRegion={selectedRegion}
                onConfigChange={setConfig}
                onRegionUpdate={updateSelectedRegion}
                onStart={handleStartTranslation}
                onAddRegion={addRegion}
            />
        </div>

      </div>
    </div>
  );
};

export default App;

