import React, { useState } from 'react';
import { TranslationConfig, RemovalType, ModelType, Region } from '../types';
import { ChevronDownIcon, ChevronRightIcon, InfoIcon, CheckCircleIcon, PlusIcon } from './Icons';
import ModelComparisonModal from './ModelComparisonModal';

interface ControlPanelProps {
  config: TranslationConfig;
  selectedRegion: Region | null;
  onConfigChange: (updates: Partial<TranslationConfig>) => void;
  onRegionUpdate: (updates: Partial<Region>) => void;
  onStart: () => void;
  onAddRegion: (type: RemovalType) => void;
}

const ControlPanel: React.FC<ControlPanelProps> = ({
  config,
  selectedRegion,
  onConfigChange,
  onRegionUpdate,
  onStart,
  onAddRegion,
}) => {
  const [showComparison, setShowComparison] = useState(false);
  const [hasSeenComparison, setHasSeenComparison] = useState(false);

  // -- Reusable Components --

  const Toggle = ({ value, onChange }: { value: boolean, onChange: (v: boolean) => void }) => (
    <div 
        onClick={() => onChange(!value)}
        className={`w-10 h-5 rounded-full relative transition-colors duration-200 cursor-pointer ${value ? 'bg-[#bef264]' : 'bg-zinc-600'}`}
    >
        <div className={`absolute top-0.5 left-0.5 w-4 h-4 bg-white rounded-full shadow-sm transition-transform duration-200 ${value ? 'translate-x-5' : 'translate-x-0'}`} />
    </div>
  );

  const RadioOption = ({ label, selected, onClick, color = 'green' }: { label: string, selected: boolean, onClick: () => void, color?: string }) => {
    let borderColor = 'border-zinc-500';
    let dotColor = '';
    let textColor = 'text-zinc-400';

    if (selected) {
        textColor = 'text-white';
        // Explicitly handle 'white' for the Advanced option
        if (color === 'white') {
            borderColor = 'border-white';
            dotColor = 'bg-white';
        } else if (color === 'green') {
            borderColor = 'border-[#bef264]';
            dotColor = 'bg-[#bef264]';
        }
    }

    return (
        <div onClick={onClick} className="flex items-center gap-2 cursor-pointer group">
            <div className={`w-4 h-4 rounded-full border flex items-center justify-center transition-colors ${borderColor} ${!selected && 'group-hover:border-zinc-400'}`}>
                {selected && <div className={`w-2 h-2 rounded-full ${dotColor}`} />}
            </div>
            <span className={`text-sm transition-colors ${textColor}`}>{label}</span>
        </div>
    );
  };

  // Helper to get current model selection (either from selected region or default BASIC)
  const currentModel = selectedRegion ? selectedRegion.model : ModelType.BASIC;
  const isRegionSelected = !!selectedRegion;

  const handleModelSelect = (model: ModelType) => {
    if (!isRegionSelected) return;

    onRegionUpdate({ model });

    // Show comparison modal on first time selecting Advanced
    if (model === ModelType.ADVANCED && !hasSeenComparison) {
        setShowComparison(true);
        setHasSeenComparison(true);
    }
  };

  return (
    <div className="bg-[#121212] flex flex-col h-full">

        {/* --- MAIN SCROLLABLE FORM --- */}
        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-7">

            {/* 1. Language Selectors */}
            <div className="flex items-center gap-3">
                <div className="flex-1 bg-zinc-900 border border-zinc-800 rounded-xl p-3 relative active:bg-zinc-800 transition-colors">
                    <div className="text-sm font-medium text-white mb-0.5">简体中文</div>
                    <div className="text-[10px] text-zinc-500">智能识别</div>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-600"><ChevronDownIcon /></div>
                </div>
                <div className="text-zinc-600"><ChevronRightIcon /></div>
                <div className="flex-1 bg-zinc-900 border border-zinc-800 rounded-xl p-3 relative active:bg-zinc-800 transition-colors">
                    <div className="text-sm font-medium text-white mb-0.5">英文English</div>
                    <div className="text-[10px] text-zinc-500">目标语言</div>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-600"><ChevronDownIcon /></div>
                </div>
            </div>

            {/* 2. Global Toggles */}
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-1.5">
                        <span className="text-sm text-zinc-300">动态视频时长</span>
                        <InfoIcon />
                    </div>
                    <Toggle value={config.dynamicDuration} onChange={(v) => onConfigChange({ dynamicDuration: v })} />
                </div>

                <div className="flex items-center justify-between">
                    <span className="text-sm text-zinc-300">采用多人配音</span>
                    <Toggle value={config.multiSpeaker} onChange={(v) => onConfigChange({ multiSpeaker: v })} />
                </div>

                <div className="flex items-center justify-between">
                    <span className="text-sm text-zinc-300">配音音色</span>
                    <div className="flex items-center gap-2 cursor-pointer">
                        <div className="w-6 h-6 rounded-full bg-amber-700 border border-amber-500 overflow-hidden">
                            <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Felix" alt="avatar" className="w-full h-full object-cover" />
                        </div>
                        <span className="text-sm text-zinc-200 font-medium">{config.voice}</span>
                        <ChevronRightIcon />
                    </div>
                </div>

                <div className="h-px bg-zinc-800/50 w-full" />

                <div className="flex items-center justify-between">
                    <span className="text-sm text-zinc-300">去除原字幕</span>
                    <Toggle value={config.removeSubtitle} onChange={(v) => onConfigChange({ removeSubtitle: v })} />
                </div>
            </div>

            {/* 3. Conditional Erasure Settings */}
            {config.removeSubtitle && (
                <div className="space-y-7 animate-in fade-in slide-in-from-top-2 duration-300">
                    {/* Add Erasure Regions */}
                    <div className="space-y-3">
                        <div className="flex items-center gap-2 mb-2">
                            <div className="w-1 h-3 bg-[#bef264] rounded-full"></div>
                            <span className="text-sm font-medium text-zinc-300">添加擦除选区</span>
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            <button 
                                onClick={() => onAddRegion(RemovalType.SUBTITLE)}
                                className="flex items-center justify-center gap-2 py-3 rounded-lg border border-[#bef264]/50 bg-[#bef264]/10 text-[#bef264] hover:bg-[#bef264]/20 active:scale-[0.98] transition-all"
                            >
                                <PlusIcon />
                                <span className="text-sm font-bold">去文字</span>
                            </button>
                            <button 
                                onClick={() => onAddRegion(RemovalType.WATERMARK)}
                                className="flex items-center justify-center gap-2 py-3 rounded-lg border border-amber-500/50 bg-amber-500/10 text-amber-400 hover:bg-amber-500/20 active:scale-[0.98] transition-all"
                            >
                                <PlusIcon />
                                <span className="text-sm font-bold">去水印/LOGO图</span>
                            </button>
                        </div>
                    </div>

                    {/* Model Selection */}
                    <div className={`space-y-3 transition-opacity duration-200 ${isRegionSelected ? 'opacity-100' : 'opacity-50'}`}>
                        <div 
                            className="flex items-center gap-1.5 w-fit" 
                            onClick={() => setShowComparison(true)}
                        >
                            <span className="text-sm text-zinc-400">选择模型</span>
                            <div className="cursor-pointer hover:text-white transition-colors">
                                <InfoIcon />
                            </div>
                        </div>
                        <div className="flex items-center gap-6 pl-1">
                            <RadioOption 
                                label="基础" 
                                selected={currentModel === ModelType.BASIC} 
                                onClick={() => handleModelSelect(ModelType.BASIC)}
                            />
                            <RadioOption 
                                label="高级" 
                                selected={currentModel === ModelType.ADVANCED} 
                                onClick={() => handleModelSelect(ModelType.ADVANCED)}
                                color="white" 
                            />
                        </div>
                        {!isRegionSelected && (
                            <div className="text-[10px] text-zinc-600 pl-1">请先选择一个选区以配置模型</div>
                        )}
                    </div>
                </div>
            )}

            {/* Spacer */}
            <div className="h-16"></div>
        </div>

        {/* --- BOTTOM START BUTTON --- */}
        <div className="p-4 bg-[#121212] border-t border-zinc-800 absolute bottom-0 left-0 right-0 z-10 pb-6">
            <button 
                onClick={onStart}
                className="w-full h-12 bg-gradient-to-r from-[#bef264] to-[#86efac] hover:to-[#4ade80] text-black font-bold text-lg rounded-full shadow-lg active:scale-[0.98] transition-all flex items-center justify-center"
            >
                开始翻译
            </button>
            <div className="absolute top-4 right-4 transform -translate-y-1/2 translate-x-1">
                <span className="bg-[#ff4d4f] text-white text-[10px] font-bold px-2 py-1 rounded-tl-lg rounded-br-lg rounded-tr-sm shadow-sm">免费试用</span>
            </div>
        </div>

        {/* Model Comparison Modal */}
        <ModelComparisonModal isOpen={showComparison} onClose={() => setShowComparison(false)} />
    </div>
  );
};

export default ControlPanel;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Region, RemovalType } from '../types';
import { MOCK_VIDEO_URL, MOCK_POSTER_URL, TYPE_COLORS } from '../constants';
import { PlayIcon, PauseIcon, PlusIcon, CopyIcon, TrashIcon, ResizeIcon, XIcon } from './Icons';

interface VideoCanvasProps {
  regions: Region[];
  selectedRegionId: string | null;
  onRegionChange: (id: string, newRegion: Partial<Region>) => void;
  onRegionSelect: (id: string | null) => void;
  isPlaying: boolean;
  onPlayToggle: () => void;
  videoState: { duration: number; currentTime: number };
  onTimeUpdate: (current: number, duration: number) => void;
  onAddFirstRegion: () => void;
  onDuplicate: () => void;
  onDelete: () => void;
  showRegions: boolean; // Control visibility
}

const VideoCanvas: React.FC<VideoCanvasProps> = ({
  regions,
  selectedRegionId,
  onRegionChange,
  onRegionSelect,
  isPlaying,
  onPlayToggle,
  videoState,
  onTimeUpdate,
  onAddFirstRegion,
  onDuplicate,
  onDelete,
  showRegions
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [hasInteracted, setHasInteracted] = useState(false);
  const [dragState, setDragState] = useState<{
    isDragging: boolean;
    isResizing: boolean;
    activeId: string | null;
    startX: number;
    startY: number;
    initialRect: Partial<Region>;
    handle?: string;
  } | null>(null);

  useEffect(() => {
    if (videoRef.current) {
      if (isPlaying) videoRef.current.play().catch(console.error);
      else videoRef.current.pause();
    }
  }, [isPlaying]);

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      onTimeUpdate(videoRef.current.currentTime, videoRef.current.duration);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const getPercentageCoordinates = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    let clientX = 0, clientY = 0;

    if ('touches' in e && e.touches.length > 0) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else if ('clientX' in e) {
      clientX = (e as MouseEvent).clientX;
      clientY = (e as MouseEvent).clientY;
    }

    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleStart = (e: React.MouseEvent | React.TouchEvent, id: string, action: 'move' | 'resize') => {
    if (!showRegions) return;
    e.stopPropagation();
    if (e.cancelable) e.preventDefault();

    // User interacted with a box, hide help text
    setHasInteracted(true);

    const region = regions.find(r => r.id === id);
    if (!region) return;

    onRegionSelect(id);
    const coords = getPercentageCoordinates(e);

    setDragState({
      isDragging: action === 'move',
      isResizing: action === 'resize',
      activeId: id,
      startX: coords.x,
      startY: coords.y,
      initialRect: { ...region }
    });
  };

  const handleMove = useCallback((e: MouseEvent | TouchEvent) => {
    if (!dragState || !dragState.activeId) return;
    if (e.cancelable) e.preventDefault();

    const coords = getPercentageCoordinates(e);
    const deltaX = coords.x - dragState.startX;
    const deltaY = coords.y - dragState.startY;
    const initial = dragState.initialRect;

    let newRegion: Partial<Region> = {};
    if (dragState.isDragging) {
      newRegion = {
        x: Math.max(0, Math.min(100 - (initial.width || 0), (initial.x || 0) + deltaX)),
        y: Math.max(0, Math.min(100 - (initial.height || 0), (initial.y || 0) + deltaY))
      };
    } else if (dragState.isResizing) {
      newRegion = {
        width: Math.max(10, (initial.width || 0) + deltaX),
        height: Math.max(5, (initial.height || 0) + deltaY)
      };
    }
    onRegionChange(dragState.activeId, newRegion);
  }, [dragState, onRegionChange]);

  const handleEnd = useCallback(() => setDragState(null), []);

  const handleDuplicate = (e: React.MouseEvent | React.TouchEvent) => {
      e.stopPropagation();
      setHasInteracted(true);
      onDuplicate();
  }

  const handleDelete = (e: React.MouseEvent | React.TouchEvent) => {
      e.stopPropagation();
      setHasInteracted(true);
      onDelete();
  }

  const handleContainerInteraction = () => {
      setHasInteracted(true);
  }

  useEffect(() => {
    if (dragState) {
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', handleEnd);
      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('touchend', handleEnd);
    }
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [dragState, handleMove, handleEnd]);

  const progressPercent = (videoState.currentTime / (videoState.duration || 1)) * 100;

  // Arrow Component
  const ArrowToBox = ({ target }: { target: Region }) => {
    const startX = 50;
    const startY = 40;
    const endX = target.x + target.width / 2;
    const endY = target.y;

    // Only show if box is somewhat below the text area
    if (endY < startY + 5) return null;

    // Bezier curve control point
    const cx = startX;
    const cy = (startY + endY) / 2;

    return (
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-20 overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
            <path 
                d={`M ${startX} ${startY + 5} Q ${cx} ${cy} ${endX} ${endY - 1}`} 
                fill="none" 
                stroke="white" 
                strokeWidth="0.5" 
                strokeDasharray="2 1"
                markerEnd="url(#arrowhead)"
                className="opacity-90 drop-shadow-md"
            />
            <defs>
                <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                    <polygon points="0 0, 6 2, 0 4" fill="white" />
                </marker>
            </defs>
        </svg>
    );
  };

  return (
    <div className="w-full space-y-2">
        <div 
            ref={containerRef} 
            className="relative w-full aspect-video bg-zinc-900 rounded-lg overflow-hidden shadow-lg touch-none group select-none"
            onMouseDown={handleContainerInteraction}
            onTouchStart={handleContainerInteraction}
        >
            <video
                ref={videoRef}
                src={MOCK_VIDEO_URL}
                poster={MOCK_POSTER_URL}
                className="w-full h-full object-cover pointer-events-none"
                playsInline
                loop
                muted
                onTimeUpdate={handleTimeUpdate}
            />

            {/* Helper Overlay - Hides on interaction */}
            {showRegions && regions.length > 0 && !hasInteracted && (
                <div className="absolute top-[20%] left-0 right-0 flex flex-col items-center justify-center text-center pointer-events-none z-10 animate-in fade-in duration-700">
                    <p className="text-white text-sm font-bold drop-shadow-lg tracking-wide">拖拽调整到合适位置和大小</p>
                    <p className="text-white/90 text-xs mt-1 drop-shadow-md">确保完整覆盖到需擦除的内容</p>
                    {(selectedRegionId || regions[0]?.id) && (
                        <ArrowToBox target={regions.find(r => r.id === (selectedRegionId || regions[0].id))!} />
                    )}
                </div>
            )}

            {/* Regions Layer */}
            {showRegions && regions.map((region) => {
                const isSelected = region.id === selectedRegionId;
                const typeStyle = TYPE_COLORS[region.type];

                return (
                    <div
                        key={region.id}
                        style={{
                            left: `${region.x}%`,
                            top: `${region.y}%`,
                            width: `${region.width}%`,
                            height: `${region.height}%`,
                            borderColor: typeStyle.primary,
                            backgroundColor: isSelected ? typeStyle.bg : 'transparent',
                            borderStyle: region.type === RemovalType.SUBTITLE ? 'dashed' : 'solid',
                        }}
                        className={`absolute border-2 touch-none transition-all duration-150
                            ${isSelected ? 'z-30' : 'z-20'}
                        `}
                        onMouseDown={(e) => handleStart(e, region.id, 'move')}
                        onTouchStart={(e) => handleStart(e, region.id, 'move')}
                    >
                        {/* Corner Controls - Only when selected */}
                        {isSelected && (
                            <>
                                {/* Top-Right: Delete (X) */}
                                <div 
                                    className="absolute -top-3 -right-3 w-6 h-6 rounded-full bg-red-500 text-white flex items-center justify-center shadow-lg z-40 cursor-pointer active:scale-90 transition-transform"
                                    onMouseDown={(e) => { e.stopPropagation(); }} 
                                    onTouchStart={(e) => { e.stopPropagation(); }}
                                    onClick={handleDelete}
                                >
                                    <XIcon />
                                </div>

                                {/* Bottom-Left: Duplicate (Copy) */}
                                <div 
                                    className="absolute -bottom-3 -left-3 w-6 h-6 rounded-full bg-zinc-700 text-white border border-zinc-500 flex items-center justify-center shadow-lg z-40 cursor-pointer active:scale-90 transition-transform"
                                    onMouseDown={(e) => { e.stopPropagation(); }} 
                                    onTouchStart={(e) => { e.stopPropagation(); }}
                                    onClick={handleDuplicate}
                                >
                                    <CopyIcon />
                                </div>

                                {/* Bottom-Right: Resize Handle */}
                                <div 
                                    className="absolute -bottom-3 -right-3 w-6 h-6 rounded-full text-white flex items-center justify-center shadow-lg z-40 cursor-nwse-resize active:scale-110 transition-transform"
                                    style={{ backgroundColor: typeStyle.primary }}
                                    onMouseDown={(e) => handleStart(e, region.id, 'resize')}
                                    onTouchStart={(e) => handleStart(e, region.id, 'resize')}
                                >
                                    <ResizeIcon />
                                </div>

                                {/* White dots for corners visual */}
                                <div className="absolute -top-1 -left-1 w-1.5 h-1.5 bg-white rounded-full pointer-events-none shadow-sm" />
                                <div className="absolute -top-1 -right-1 w-1.5 h-1.5 bg-white rounded-full pointer-events-none shadow-sm" />
                                <div className="absolute -bottom-1 -left-1 w-1.5 h-1.5 bg-white rounded-full pointer-events-none shadow-sm" />
                                <div className="absolute -bottom-1 -right-1 w-1.5 h-1.5 bg-white rounded-full pointer-events-none shadow-sm" />
                            </>
                        )}
                    </div>
                );
            })}
        </div>

        {/* Minimal Player Controls */}
        <div className="flex items-center gap-3 px-1 py-1">
            <button onClick={onPlayToggle} className="text-white hover:text-[#bef264] transition-colors">
                {isPlaying ? <PauseIcon /> : <PlayIcon />}
            </button>

            <div className="flex-1 relative h-6 flex items-center group cursor-pointer">
                <div className="absolute left-0 right-0 h-0.5 bg-zinc-700 rounded-full"></div>
                <div className="absolute left-0 h-0.5 bg-[#bef264] rounded-full" style={{ width: `${progressPercent}%` }}></div>
                <div className="absolute h-3 w-3 bg-white rounded-full shadow-md transform -translate-x-1/2" style={{ left: `${progressPercent}%` }}></div>
            </div>

            <div className="text-[10px] font-mono text-zinc-400">
                <span className="text-white">{formatTime(videoState.currentTime)}</span>
                <span className="opacity-50">/{formatTime(videoState.duration)}</span>
            </div>
        </div>
    </div>
  );
};

export default VideoCanvas;
